fn is_non_prime(n: u64) -> bool {
    // By definition, numbers less than 2 are not considered here;
    // we assume n >= 2 per the problem statement, but handle it gracefully.
    if n < 2 {
        return false;
    }

    // A non-trivial divisor k of n must satisfy 2 <= k <= sqrt(n).
    // We avoid overflow by testing k <= n / k instead of k * k <= n.
    let mut k = 2;
    while k <= n / k {
        if n % k == 0 {
            return true;
        }
        k += 1;
    }

    // No divisor found => n is prime
    false
}